/* 4x5 Button Grid wrapper */
.button-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px; /* grid-gap */
}

/* Standard Tactical interactive button element */
.calc-button {
  aspect-ratio: 1; /* Squarish desktop ratio */
  min-height: 48px; /* Interactive mobile tap target clearance min */
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  font-size: 20px;
  font-weight: 600;
  border-radius: 8px; /* rounded-button */
  border: var(--border-btn);
  box-shadow: var(--shadow-btn);
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  transition: transform 0.1s ease-in-out, background-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
  outline: none;
}

/* Active plunge transforms simulating physical plunger button travel */
.calc-button:active:not(:disabled) {
  transform: scale(0.97);
  box-shadow: none;
}

.calc-button:focus-visible {
