import ast
import decimal
from backend.app.engine.evaluator import SafeMathEvaluator

class MathEvaluationError(ValueError):
    """Custom domain exception raised for mathematical evaluation or syntax errors."""
    pass

def safe_parse_and_evaluate(expression: str) -> decimal.Decimal:
    """Parses a mathematical expression string into a Python AST and evaluates it safely

    using a custom safe visitor pattern.

    All mathematical, syntax, and whitelisting exceptions are caught and wrapped
    into a standardized MathEvaluationError domain exception.
    """
    if not isinstance(expression, str):
        raise MathEvaluationError("Error: Input expression must be a string")

    cleaned_expr = expression.strip()
    if not cleaned_expr:
        raise MathEvaluationError("Error: Expression is empty")

    try:
        # ast.parse with mode='eval' compiles strictly as a single evaluation expression,
        # never as multiple statements. This is highly secure.
        tree = ast.parse(cleaned_expr, mode='eval')
    except SyntaxError as err:
        error_msg = str(err).lower()
        if "unmatched" in error_msg or "never closed" in error_msg or "unclosed" in error_msg:
            raise MathEvaluationError("Error: Unbalanced parentheses") from err
        raise MathEvaluationError("Error: Invalid syntax structure") from err

    evaluator = SafeMathEvaluator()
    try:
        return evaluator.evaluate(tree)
    except (ZeroDivisionError, decimal.DivisionByZero) as err:
        raise MathEvaluationError("Error: Division by zero") from err
    except (TypeError, ValueError) as err:
        err_msg = str(err)
        # Preserve whitelisting syntax node errors
        if "Error: Forbidden syntax node" in err_msg:
            raise MathEvaluationError(err_msg) from err
        raise MathEvaluationError(f"Error: Invalid expression: {err_msg}") from err
    except Exception as err:
        raise MathEvaluationError(f"Error: Evaluation failed: {str(err)}") from err

import ast
from decimal import Decimal, localcontext

class SafeMathEvaluator(ast.NodeVisitor):
    """Custom NodeVisitor that safely evaluates mathematical expression trees

    using arbitrary-precision Decimal arithmetic.
    """
    # Allowed binary operators mapped to Decimal operations
    BIN_OPS = {
        ast.Add: lambda a, b: a + b,
        ast.Sub: lambda a, b: a - b,
        ast.Mult: lambda a, b: a * b,
        ast.Div: lambda a, b: a / b,
    }

    # Allowed unary operators mapped to Decimal operations
    UNARY_OPS = {
        ast.UAdd: lambda a: +a,
        ast.USub: lambda a: -a,
    }

    def evaluate(self, node: ast.AST) -> Decimal:
        # Evaluate within a local context to prevent modifying the global process context
        with localcontext() as ctx:
            ctx.prec = 28
            result = self.visit(node)
            if not isinstance(result, Decimal):
                raise TypeError(f"Evaluation resulted in unexpected type: {type(result).__name__}")
            return result

    def visit_Expression(self, node: ast.Expression):
        return self.visit(node.body)

    def visit_Constant(self, node: ast.Constant) -> Decimal:
        # Boolean is a subclass of int in Python, so block booleans explicitly
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise TypeError(f"Unsupported constant type: {type(node.value).__name__}")
        # Convert floats to string first to prevent IEEE-754 binary conversion noise
        return Decimal(str(node.value))

    def visit_BinOp(self, node: ast.BinOp) -> Decimal:
        op_type = type(node.op)
        if op_type not in self.BIN_OPS:
            raise TypeError(f"Unsupported binary operator: {op_type.__name__}")

        left_val = self.visit(node.left)
        right_val = self.visit(node.right)

        # Division by zero will be intercepted natively or by decimal module
        return self.BIN_OPS[op_type](left_val, right_val)

    def visit_UnaryOp(self, node: ast.UnaryOp) -> Decimal:
        op_type = type(node.op)
        if op_type not in self.UNARY_OPS:
            raise TypeError(f"Unsupported unary operator: {op_type.__name__}")

        operand_val = self.visit(node.operand)
        return self.UNARY_OPS[op_type](operand_val)

    def generic_visit(self, node: ast.AST):
        """Block any syntax nodes that are not explicitly whitelisted."""
        raise ValueError(f"Error: Forbidden syntax node: {type(node).__name__}")

from typing import Literal
from fastapi import APIRouter, status
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field
from backend.app.engine.parser import safe_parse_and_evaluate, MathEvaluationError

router = APIRouter(prefix="/api/v1")

class EvaluateRequest(BaseModel):
    expression: str = Field(..., description="The mathematical expression to evaluate", example="12.5 + 3 * (4 - 1.5) / 2")

class EvaluateResponse(BaseModel):
    status: Literal["success"] = Field("success", description="The status of the evaluation")
    expression: str = Field(..., description="The original evaluated expression")
    result: str = Field(..., description="The mathematically exact calculated decimal result represented as a string")

class ErrorResponse(BaseModel):
    status: Literal["error"] = Field("error", description="The status of the error")
    error_type: str = Field(..., description="The specific classification code of the mathematical error")
    message: str = Field(..., description="The formatted user-facing error message starting with 'Error: '")

@router.post(
    "/evaluate",
    response_model=EvaluateResponse,
    responses={
        422: {"model": ErrorResponse, "description": "Unprocessable mathematical or syntactical expression"}
    }
)
async def evaluate_expression(payload: EvaluateRequest):
    try:
        result_decimal = safe_parse_and_evaluate(payload.expression)
        return EvaluateResponse(
            expression=payload.expression,
            result=str(result_decimal)
        )
    except MathEvaluationError as err:
        err_msg = str(err)
        # Determine specific error classification token
        error_type = "invalid_expression"
        if "division by zero" in err_msg.lower():
            error_type = "division_by_zero"
        elif "unbalanced parentheses" in err_msg.lower():
            error_type = "unbalanced_parentheses"
        elif "empty" in err_msg.lower():
            error_type = "empty_expression"

        return JSONResponse(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            content={
                "status": "error",
                "error_type": error_type,
                "message": err_msg
            }
        )

