  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.drawer-header h3 {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
}

.drawer-close-btn {
  background: none;
  border: none;
  font-size: 24px;
  cursor: pointer;
  color: var(--text-result-preview);
  line-height: 1;
}

.drawer-body {
  flex: 1;
  overflow-y: auto;
  max-height: 400px;
  scrollbar-width: thin;
}

.no-history-msg {
  color: var(--text-result-preview);
  font-size: 14px;
  text-align: center;
  margin-top: 40px;
}

.history-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.history-item-row {
  background-color: var(--bg-display);
  border-radius: 8px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  box-shadow: var(--shadow-btn);
}

.history-expr-preview {
